class Counter {
	private static instance: Counter | undefined;
	private value = 0;

	static getInstance(): Counter {
		Counter.instance ??= new Counter();
		return Counter.instance;
	}

	increment(): number {
		return ++this.value;
	}
}

test("first", () => {
	expect(Counter.getInstance().increment()).toBe(1);
});

test("second", () => {
	expect(Counter.getInstance().increment()).toBe(1);
});

