class RequestBuilder {
	private headers: string[] = [];

	header(value: string): this {
		this.headers.push(value);
		return this;
	}

	build(): Request {
		return new Request(this.headers);
	}
}

const builder = new RequestBuilder().header("A");
const first = builder.build();
const second = builder.header("B").build();

